def check_numeric_characters(file_name):
    return sum(c.isdigit() for c in file_name) <= 3

def check_period_count(file_name):
    return file_name.count('.') == 1

def check_start_with_letter(file_name):
    segments = file_name.split('.')
    if len(segments) < 2:
        return False
    return segments[0].isalpha()

def check_extension(file_name):
    segments = file_name.split('.')
    if len(segments) < 2:
        return False
    return segments[1] in ['txt', 'exe', 'dll']

def file_name_check(file_name):
    return 'Yes' if all([check_numeric_characters(file_name), check_period_count(file_name), 
                         check_start_with_letter(file_name), check_extension(file_name)]) else 'No'

