def file_name_check(file_name):
    if not isinstance(file_name, str):
        return 'No'

    if len(file_name) < 5:
        return 'No'

    if file_name.count('.') != 1:
        return 'No'

    segments = file_name.split('.')
    if not segments[0].isalpha():
        return 'No'

    if segments[1] not in ['txt', 'exe', 'dll']:
        return 'No'

    if sum(c.isdigit() for c in file_name) > 3:
        return 'No'

    return 'Yes'
